#include "aitoolbox/data.hpp"
#include <cassert>
#include <cmath>
#include <iostream>
int main() {
    auto s = aitoolbox::group_split({"a1","a2","b1","b2"}, {"piece_a","piece_a","piece_b","piece_b"}, .5, 42);
    assert(s.train.size()==2 && s.test.size()==2);
    assert(s.train[0][0]!=s.test[0][0]);
    std::cout << s.train.size() << " train / " << s.test.size() << " test\n";
}

